import assert from "node:assert/strict";
import { test } from "node:test";
import {
	BASE_CSS,
	COMPONENTS,
	HtmlError,
	analyzeDocument,
	buildMetrics,
	compareMetrics,
	componentsMarkdown,
	fillDocument,
	parseArgs,
	resolvePagePath,
	scratchDocument,
	snippetClasses,
	usedComponentIds
} from "../index.js";

/* ------------------------------------------------------------- catalogue */

test("the catalogue is a real kit: unique ids, every entry has a snippet", () => {
	assert.ok(COMPONENTS.length >= 12, `expected a usable kit, got ${COMPONENTS.length}`);
	const ids = new Set();
	for (const one of COMPONENTS) {
		assert.ok(one.id.length > 0 && !ids.has(one.id), `duplicate id ${one.id}`);
		ids.add(one.id);
		assert.ok(one.when.length > 0, `${one.id} needs a "when to use" line`);
		assert.ok(one.snippet.trim().length > 0, `${one.id} needs a snippet`);
	}
});

test("the kit covers charts and a sortable table", () => {
	const ids = COMPONENTS.map((one) => one.id);
	for (const wanted of ["chart-bars", "chart-donut", "table-sortable"]) {
		assert.ok(ids.includes(wanted), `missing component ${wanted}`);
	}
	const sortable = COMPONENTS.find((one) => one.id === "table-sortable");
	assert.ok(sortable.snippet.includes("<script>"), "sorting is inline, progressive enhancement");
	assert.equal(/https?:\/\//.test(sortable.snippet), false, "no external script");
	assert.ok(sortable.snippet.includes("data-page-size"), "pagination is data-driven");
});

test("every class a snippet uses is defined by the shipped stylesheet", () => {
	const style = BASE_CSS.replace("__ACCENT__", "#000");
	const missing = snippetClasses().filter((cls) => !style.includes(`.${cls}`));
	assert.deepEqual(missing, [], `classes used by snippets but absent from BASE_CSS: ${missing.join(", ")}`);
});

test("the stylesheet itself is offline-safe and theme-aware", () => {
	assert.equal(/https?:\/\//.test(BASE_CSS), false, "BASE_CSS must not reference the network");
	assert.ok(BASE_CSS.includes("prefers-color-scheme"), "dark mode is part of the kit");
	assert.ok(BASE_CSS.includes("--accent"), "accent token must exist so create() can recolour a page");
});

test("chart components are pure CSS or static SVG: no script needed", () => {
	for (const id of ["chart-bars", "chart-donut", "chart-stack", "chart-hbars", "chart-line", "chart-heat"]) {
		const one = COMPONENTS.find((entry) => entry.id === id);
		assert.equal(/<script/.test(one.snippet), false, `${id} must not need JavaScript`);
		assert.equal(/https?:\/\//.test(one.snippet), false, `${id} must not reach the network`);
	}
	// Bar-shaped charts size themselves with percentages; line/heat are drawn
	// by coordinates or intensity classes.
	for (const id of ["chart-bars", "chart-stack", "chart-hbars"]) {
		const one = COMPONENTS.find((entry) => entry.id === id);
		assert.ok(/style="[^"]*%/.test(one.snippet), `${id} sizes itself with inline percentages`);
	}
	assert.ok(COMPONENTS.find((entry) => entry.id === "chart-line").snippet.includes("viewBox"));
	assert.ok(COMPONENTS.find((entry) => entry.id === "chart-heat").snippet.includes("heat-cell l3"));
});

test("the catalogue can be narrowed to the components a page needs", () => {
	const md = componentsMarkdown(["card", "steps"]);
	assert.ok(md.includes("## card"));
	assert.ok(md.includes("## steps"));
	assert.equal(md.includes("## table"), false);
	assert.ok(md.includes("```html"));
});

/* ---------------------------------------------------------------- template */

test("create writes a self-contained, mobile-first document", () => {
	const page = scratchDocument({ title: "训练计划", eyebrow: "8 周", content: "<p>hi</p>" });
	assert.ok(page.startsWith("<!doctype html>"));
	assert.ok(page.includes('name="viewport"'));
	assert.ok(page.includes("prefers-color-scheme"));
	assert.ok(page.includes("<!-- dsh:content -->"));
	assert.ok(page.includes("<!-- dsh:content:end -->"));
	assert.ok(page.includes("<!-- dsh:end -->"));
	assert.equal(/https?:\/\//.test(page), false, "a generated page must not need the network");
	assert.equal(/window\.print/.test(page), false, "the shell owns printing");
	assert.equal(/<script[^>]+src=/.test(page), false, "no external scripts");
});

test("an accent passed by the caller reaches the page, and unsafe titles are escaped", () => {
	const page = scratchDocument({ title: "<b>x</b>", accent: "#f2542d" });
	assert.ok(page.includes("--accent: #f2542d"));
	assert.ok(page.includes("&lt;b&gt;x&lt;/b&gt;"));
});

/* -------------------------------------------------------------------- fill */

test("fill replaces the content slot and keeps the skeleton", () => {
	const base = scratchDocument({ title: "t" });
	const filled = fillDocument(base, '<section class="card">A</section>', "replace");
	assert.ok(filled.includes('<section class="card">A</section>'));
	assert.ok(filled.includes("<!-- dsh:content -->"));
	assert.ok(filled.indexOf('<section class="card">A</section>') < filled.indexOf("<!-- dsh:content:end -->"));
	assert.ok(filled.indexOf('<section class="card">A</section>') < filled.indexOf("</main>"));
});

test("fill with append adds another section inside <main>, not after the footer", () => {
	let page = scratchDocument({ title: "t", content: "<p>one</p>" });
	page = fillDocument(page, "<p>two</p>", "append");
	assert.ok(page.includes("<p>one</p>"));
	assert.ok(page.includes("<p>two</p>"));
	assert.ok(page.indexOf("<p>two</p>") < page.indexOf("<!-- dsh:content:end -->"));
	assert.ok(page.indexOf("<p>two</p>") < page.indexOf("</main>"), "appended content must stay inside <main>");
	assert.ok(page.indexOf("<p>two</p>") < page.indexOf("<footer"), "appended content must come before the footer");
});

test("fill refuses a page that has no markers", () => {
	assert.throws(() => fillDocument("<html></html>", "<p>x</p>", "replace"), (error) => {
		return error instanceof HtmlError && error.code === "HTML_NO_MARKER";
	});
});

/* ------------------------------------------------------------------- paths */

test("page paths must stay inside the workspace", () => {
	assert.equal(resolvePagePath("/w", "plan.html").relative, "plan.html");
	assert.equal(resolvePagePath("/w", "sub/plan.htm").relative, "sub/plan.htm");
	for (const bad of ["/etc/x.html", "../x.html", "a/../../x.html"]) {
		assert.throws(() => resolvePagePath("/w", bad), (error) => error.code === "HTML_BAD_PATH", bad);
	}
});

test("only html files are pages", () => {
	for (const bad of ["a.md", "a.js", "noext"]) {
		assert.throws(() => resolvePagePath("/w", bad), (error) => error.code === "HTML_BAD_PATH", bad);
	}
});

/* ------------------------------------------------------------------ checks */

test("a page built from the kit passes check", () => {
	const page = scratchDocument({
		title: "t",
		content: '<div class="stats"><div class="stat"><div class="stat-value">5</div></div></div>'
	});
	const report = analyzeDocument(page, { path: "a.html" });
	assert.deepEqual(report.errors, []);
	assert.deepEqual(report.warnings, []);
	assert.equal(report.ok, true);
});

test("external references are errors, with the line number", () => {
	const page = scratchDocument({ title: "t", content: '<img src="https://example.com/a.png">' });
	const report = analyzeDocument(page, { path: "a.html" });
	assert.equal(report.ok, false);
	assert.ok(report.errors.some((one) => one.includes("远程媒体")));
	assert.ok(report.errors.some((one) => /第 \d+ 行/.test(one)));
});

test("a missing viewport is a hard error: desktop width on a phone", () => {
	const report = analyzeDocument("<html><body><h1>x</h1></body></html>", { path: "a.html" });
	assert.ok(report.errors.some((one) => one.includes("viewport")));
});

test("a print button is a warning, because the shell owns exporting", () => {
	const report = analyzeDocument(
		'<html><head><meta name="viewport" content="x"><style>:root{color-scheme:light dark}</style></head>' +
		'<body><h1>x</h1><button onclick="window.print()">打印</button></body></html>',
		{ path: "a.html" }
	);
	assert.ok(report.warnings.some((one) => one.includes("window.print")));
});

test("a second stylesheet and unknown classes are reported as drift", () => {
	const report = analyzeDocument(
		'<html><head><meta name="viewport" content="x"><style>a{}</style><style>.mine{}</style></head>' +
		'<body><h1>x</h1><div class="my-own-thing">y</div></body></html>',
		{ path: "a.html" }
	);
	assert.ok(report.warnings.some((one) => one.includes("<style>")));
	assert.ok(report.warnings.some((one) => one.includes("my-own-thing")));
});

test("the size ceiling is an error, not a silent trim", () => {
	const report = analyzeDocument(scratchDocument({ title: "t" }), { path: "a.html", maxKb: 0.1 });
	assert.ok(report.errors.some((one) => one.includes("超过上限")));
});

/* -------------------------------------------------------------------- args */

test("unknown actions and missing paths are refused with a code", () => {
	assert.throws(() => parseArgs({ action: "paint", path: "a.html" }), (error) => error.code === "HTML_BAD_ARGS");
	assert.throws(() => parseArgs({ action: "create" }), (error) => error.code === "HTML_BAD_ARGS");
	assert.throws(() => parseArgs({ action: "create", path: "a.html", accent: "red" }), (error) => error.code === "HTML_BAD_ARGS");
	assert.throws(() => parseArgs({ action: "fill", path: "a.html", mode: "sideways" }), (error) => error.code === "HTML_BAD_ARGS");
});

test("components does not need a path, and component filters are kept", () => {
	const parsed = parseArgs({ action: "components", components: ["card"] });
	assert.equal(parsed.action, "components");
	assert.deepEqual(parsed.components, ["card"]);
});

/* --------------------------------------------------------------- baseline */

test("usedComponentIds follows the classes actually present", () => {
	const page = scratchDocument({
		title: "t",
		content: '<div class="stats"><div class="stat"><div class="stat-value">1</div></div></div>' +
			'<ol class="steps"><li class="step"><span class="step-num">1</span></li></ol>'
	});
	const used = usedComponentIds(page);
	assert.ok(used.includes("stats"));
	assert.ok(used.includes("steps"));
	assert.equal(used.includes("table"), false);
});

test("the first check records a baseline instead of comparing", () => {
	const metrics = buildMetrics(scratchDocument({ title: "t" }), { sizeKb: 8, warnings: [], errors: [] }, "t0");
	const lines = compareMetrics(null, metrics);
	assert.equal(lines.length, 1);
	assert.ok(lines[0].includes("baseline"));
	assert.ok(lines[0].includes("8KB"));
});

test("a second check reports size, component and problem deltas", () => {
	const before = { at: "t0", sizeKb: 8, components: ["card"], warnings: 0, errors: 0 };
	const after = { at: "t1", sizeKb: 12, components: ["card", "stats"], warnings: 1, errors: 0 };
	const lines = compareMetrics(before, after).join("\n");
	assert.ok(lines.includes("8KB → 12KB"));
	assert.ok(lines.includes("+50%"));
	assert.ok(lines.includes("新增组件 stats"));
	assert.ok(lines.includes("问题数 0/0（warn/error）→ 1/0"));
});

test("an unchanged page says so instead of staying silent", () => {
	const metrics = { at: "t1", sizeKb: 8, components: ["card"], warnings: 0, errors: 0 };
	const lines = compareMetrics({ ...metrics, at: "t0" }, metrics).join("\n");
	assert.ok(lines.includes("体积持平"));
	assert.ok(lines.includes("组件与上次一致"));
});

test("inline progressive-enhancement scripts are allowed; only external ones are errors", () => {
	const page = scratchDocument({
		title: "t",
		content: '<table class="sortable"><thead><tr><th class="sortable">a</th></tr></thead><tbody><tr><td>1</td></tr></tbody></table>' +
			'<script>window.dshReady = true;</script>'
	});
	const report = analyzeDocument(page, { path: "a.html" });
	assert.deepEqual(report.errors, []);
});

/* ------------------------------------------------- sortable table behaviour */

/** The smallest DOM the sortable snippet touches, just enough to run it. */
function fakeTable(rows) {
	const makeCell = (text) => ({
		textContent: String(text),
		classList: { contains: () => false },
		getAttribute: () => null,
		setAttribute: () => {}
	});
	const makeRow = (values) => ({ cells: values.map((one) => makeCell(one)) });
	const body = {
		rows: rows.map((one) => makeRow(one)),
		children: [],
		get firstChild() { return this.children.length > 0 ? this.children[0] : null; },
		removeChild() { this.children.shift(); },
		appendChild(row) { this.children.push(row); }
	};
	let sortHandler = null;
	const head = {
		getAttribute: (key) => (key === "data-type" ? "number" : null),
		setAttribute: () => {},
		classList: { contains: () => true },
		set onclick(handler) { sortHandler = handler; },
		get onclick() { return sortHandler; }
	};
	const table = {
		tBodies: [body],
		tHead: { rows: [{ cells: [{ ...makeCell("动作"), classList: { contains: () => true }, getAttribute: () => "text" }, head] }] },
		getAttribute: (key) => (key === "data-page-size" ? "8" : null),
		setAttribute: () => {},
		closest: () => null,
		parentNode: { insertBefore: () => {} }
	};
	return { table, body, head };
}

test("the inline script sorts rows by the clicked column and pages them", () => {
	const snippet = COMPONENTS.find((one) => one.id === "table-sortable").snippet;
	const code = snippet.slice(snippet.indexOf("<script>") + 8, snippet.indexOf("</script>"));
	const { table, body, head } = fakeTable([["深蹲", "4"], ["硬拉", "3"], ["卧推", "5"], ["划船", "2"]]);
	const document = {
		querySelectorAll: () => [table],
		createElement: () => ({ appendChild: () => {}, setAttribute: () => {}, set textContent(value) {}, onclick: null }),
	};
	// The script is a plain IIFE; run it against the fake document.
	new Function("document", code)(document);
	assert.equal(body.children.length, 4, "eight-row page size shows every row");
	assert.deepEqual(body.children.map((row) => row.cells[1].textContent), ["4", "3", "5", "2"]);

	head.onclick();
	assert.deepEqual(body.children.map((row) => row.cells[1].textContent), ["2", "3", "4", "5"], "first click sorts ascending");

	head.onclick();
	assert.deepEqual(body.children.map((row) => row.cells[1].textContent), ["5", "4", "3", "2"], "second click reverses");

	head.onclick();
	assert.deepEqual(body.children.map((row) => row.cells[1].textContent), ["2", "3", "4", "5"], "third click returns to ascending");
});

/* ------------------------------------------------------ tokens & variants */

test("the catalogue teaches tokens and modifiers, not just snippets", () => {
	const md = componentsMarkdown();
	assert.ok(md.includes("## 令牌"), "token sheet must be part of the catalogue");
	assert.ok(md.includes("--accent"));
	assert.ok(md.includes("--c1 … --c5"));
	assert.ok(md.includes("## 修饰符"));
	assert.ok(md.includes("card.flat"));
});

test("create applies token overrides and layout variants", () => {
	const page = scratchDocument({
		title: "t",
		tokens: { "--accent": "#c2410c", "--c2": "#0891b2", "--gap": "24px" },
		width: "wide",
		density: "compact",
		theme: "dark"
	});
	assert.ok(page.includes('data-theme="dark"'));
	assert.ok(page.includes("--accent:#c2410c"));
	assert.ok(page.includes("--c2:#0891b2"));
	assert.ok(page.includes('class="wrap wide"'));
	assert.ok(page.includes('class="density-compact"'));
});

test("an explicit theme wins over the system preference", () => {
	const dark = scratchDocument({ title: "t", theme: "dark" });
	assert.ok(dark.includes("html[data-theme=\"dark\"]"));
	assert.ok(dark.includes('@media (prefers-color-scheme: dark) {\n  html:not([data-theme="light"])'), "auto mode is the fallback, not the override");
});

test("bad token names, themes, widths and densities are refused", () => {
	assert.throws(() => parseArgs({ action: "create", path: "a.html", tokens: { accent: "#000" } }), (error) => error.code === "HTML_BAD_ARGS");
	assert.throws(() => parseArgs({ action: "create", path: "a.html", theme: "sepia" }), (error) => error.code === "HTML_BAD_ARGS");
	assert.throws(() => parseArgs({ action: "create", path: "a.html", width: "full" }), (error) => error.code === "HTML_BAD_ARGS");
	assert.throws(() => parseArgs({ action: "create", path: "a.html", density: "airy" }), (error) => error.code === "HTML_BAD_ARGS");
});

test("hard-coded colours in the page body are reported, tokens are not", () => {
	const clean = scratchDocument({ title: "t", tokens: { "--accent": "#c2410c" }, content: '<p class="text-accent">hi</p>' });
	assert.deepEqual(analyzeDocument(clean, { path: "a.html" }).warnings, []);

	const painted = scratchDocument({
		title: "t",
		content: '<div style="color:#123456">a</div><div style="background:#abcdef">b</div>' +
			'<div style="border-color:#fedcba">c</div><div style="color:#0f0">d</div>'
	});
	const report = analyzeDocument(painted, { path: "a.html" });
	assert.ok(report.warnings.some((one) => one.includes("写死了 4 个十六进制颜色")));
});

test("the new display components are shipped and covered by the stylesheet", () => {
	for (const id of ["section-head", "figure", "gallery", "avatars", "plans"]) {
		assert.ok(COMPONENTS.some((one) => one.id === id), `missing ${id}`);
	}
	const style = BASE_CSS.replace("__ACCENT__", "#000");
	for (const cls of ["plan-price", "avatar-name", "figure-cap", "hbar-fill", "stack-seg", "heat-cell"]) {
		assert.ok(style.includes(`.${cls}`), `${cls} must exist in BASE_CSS`);
	}
});
